from __future__ import annotations

import ast
import hashlib
import importlib
import inspect
import json
import pickle
import sys
from pathlib import Path
from typing import get_type_hints

ROOT = Path(__file__).resolve().parents[1]
BACKEND = ROOT / "backend"
sys.path.insert(0, str(BACKEND))
OUT = ROOT / "docs/audit/dashboard-2026-10-30"
PUBLIC = "app.infrastructure.database.models"


def symbol(value):
    return f"{value.__module__}.{value.__qualname__}"


def stable(value):
    from sqlalchemy.sql.elements import ClauseElement

    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, dict):
        return {str(key): stable(item) for key, item in sorted(value.items())}
    if isinstance(value, (tuple, list)):
        return [stable(item) for item in value]
    if isinstance(value, (set, frozenset)):
        return sorted(stable(item) for item in value)
    if isinstance(value, ClauseElement):
        return str(value.compile(compile_kwargs={"literal_binds": True}))
    if callable(value):
        return {"callable": symbol(value), "unwrapped": symbol(inspect.unwrap(value))}
    return {"type": symbol(type(value)), "value": str(value)}


def default(value):
    if value is None:
        return None
    return {"type": symbol(type(value)), "arg": stable(getattr(value, "arg", None)), "for_update": getattr(value, "for_update", None)}


def type_metadata(value, dialects):
    return {"type": symbol(type(value)), "compiled": {name: str(value.compile(dialect=dialect)) for name, dialect in dialects.items()}, "flags": {key: stable(getattr(value, key, None)) for key in ["name", "length", "timezone", "precision", "scale", "enums", "native_enum", "create_type", "create_constraint", "validate_strings", "as_uuid"]}, "variants": {key: symbol(type(item)) for key, item in sorted(getattr(value, "_variant_mapping", {}).items())}}


def ddl_if(value):
    condition = getattr(value, "_ddl_if", None)
    return None if condition is None else {"dialect": stable(condition.dialect), "callable": stable(condition.callable_), "state": stable(condition.state)}


def snapshot(entry):
    from sqlalchemy import inspect as orm_inspect
    from sqlalchemy.dialects import postgresql, sqlite
    from sqlalchemy.orm import configure_mappers
    from sqlalchemy.schema import CreateIndex, CreateTable

    importlib.import_module(entry)
    importlib.import_module("app.infrastructure.database.model_registry")
    from app.infrastructure.database import model_base, models

    configure_mappers()
    assert models.Base is model_base.Base
    assert models.JSONB is model_base.JSONB
    assert models._utcnow is model_base._utcnow
    dialects = {"postgresql": postgresql.dialect(), "sqlite": sqlite.dialect()}
    source = json.loads((OUT / "core-models-original-source.json").read_text(encoding="utf-8"))["source"]
    original_classes = [node.name for node in ast.parse(source).body if isinstance(node, ast.ClassDef)]
    metadata = models.Base.metadata
    tables = {}
    compile_errors = []
    for key, table in sorted(metadata.tables.items()):
        columns = []
        for column in table.columns:
            columns.append({"name": column.name, "key": column.key, "type": type_metadata(column.type, dialects), "nullable": column.nullable, "primary_key": column.primary_key, "autoincrement": stable(column.autoincrement), "unique": column.unique, "index": column.index, "default": default(column.default), "onupdate": default(column.onupdate), "server_default": default(column.server_default), "server_onupdate": default(column.server_onupdate), "comment": column.comment, "info": stable(column.info)})
        constraints = []
        for constraint in table.constraints:
            constraints.append({"type": symbol(type(constraint)), "name": constraint.name, "columns": [column.name for column in constraint.columns], "sqltext": stable(getattr(constraint, "sqltext", None)), "foreign_keys": [{"local": element.parent.name, "target": element.target_fullname} for element in getattr(constraint, "elements", [])], "flags": {name: stable(getattr(constraint, name, None)) for name in ["ondelete", "onupdate", "deferrable", "initially", "use_alter", "match"]}, "ddl_if": ddl_if(constraint)})
        constraints.sort(key=lambda item: (item["type"], str(item["name"]), json.dumps(item["columns"])))
        indexes = []
        for index in sorted(table.indexes, key=lambda item: str(item.name)):
            compiled = {}
            for name, dialect in dialects.items():
                try:
                    compiled[name] = str(CreateIndex(index).compile(dialect=dialect))
                except Exception as exc:
                    compiled[name] = {"error_type": symbol(type(exc)), "message": str(exc)}
                    compile_errors.append({"table": key, "index": index.name, "dialect": name, **compiled[name]})
            indexes.append({"name": index.name, "unique": index.unique, "expressions": [stable(item) for item in index.expressions], "dialect_options": {name: stable(dict(index.dialect_options[name])) for name in ["postgresql", "sqlite"]}, "ddl_if": ddl_if(index), "compiled": compiled})
        compiled_tables = {}
        for name, dialect in dialects.items():
            try:
                compiled_tables[name] = str(CreateTable(table).compile(dialect=dialect))
            except Exception as exc:
                compiled_tables[name] = {"error_type": symbol(type(exc)), "message": str(exc)}
                compile_errors.append({"table": key, "dialect": name, **compiled_tables[name]})
        tables[key] = {"schema": table.schema, "comment": table.comment, "info": stable(table.info), "columns": columns, "constraints": constraints, "indexes": indexes, "compiled": compiled_tables}
    mappers = {}
    for mapper in sorted(models.Base.registry.mappers, key=lambda item: item.local_table.fullname):
        relations = {}
        for relation in mapper.relationships:
            relations[relation.key] = {"target": symbol(relation.mapper.class_), "target_table": relation.mapper.local_table.fullname, "direction": relation.direction.name, "uselist": relation.uselist, "back_populates": relation.back_populates, "cascade": sorted(relation.cascade), "viewonly": relation.viewonly, "lazy": relation.lazy, "primaryjoin": stable(relation.primaryjoin), "secondary": None if relation.secondary is None else relation.secondary.fullname, "secondaryjoin": stable(relation.secondaryjoin), "local_remote_pairs": [[f"{left.table.fullname}.{left.name}", f"{right.table.fullname}.{right.name}"] for left, right in relation.local_remote_pairs], "foreign_keys": sorted(f"{column.table.fullname}.{column.name}" for column in relation._calculated_foreign_keys), "flags": {name: stable(getattr(relation, name)) for name in ["passive_deletes", "passive_updates", "innerjoin", "single_parent", "post_update", "sync_backref", "enable_typechecks", "distinct_target_key"]}}
        mappers[mapper.local_table.fullname] = {"class": symbol(mapper.class_), "columns": list(mapper.columns.keys()), "primary_key": [column.name for column in mapper.primary_key], "relationships": relations}
    classes = {}
    module_registry = models.Base.registry._class_registry["_sa_module_registry"]
    namespace = module_registry.mod_ns
    for component in PUBLIC.split("."):
        namespace = getattr(namespace, component)
    for name in original_classes:
        cls = getattr(models, name)
        try:
            hints = {"ok": True, "hints": {key: repr(value) for key, value in get_type_hints(cls).items()}}
        except Exception as exc:
            hints = {"ok": False, "error_type": symbol(type(exc)), "message": str(exc)}
        mapped = hasattr(cls, "__table__")
        if mapped:
            mapper = orm_inspect(cls)
            assert mapper.local_table is metadata.tables[cls.__tablename__]
            assert mapper.class_ is cls
            assert models.Base.registry._class_registry[name] is cls
            assert getattr(namespace, name) is cls
        assert pickle.loads(pickle.dumps(cls)) is cls
        try:
            signature = {"ok": True, "value": str(inspect.signature(cls))}
        except (TypeError, ValueError) as exc:
            signature = {"ok": False, "error_type": symbol(type(exc)), "message": str(exc)}
        classes[name] = {"module": cls.__module__, "qualname": cls.__qualname__, "mro": [symbol(item) for item in cls.__mro__], "signature": signature, "annotations": {key: value if isinstance(value, str) else repr(value) for key, value in cls.__annotations__.items()}, "get_type_hints": hints, "mapped": mapped, "table": cls.__tablename__ if mapped else None, "public_pickle_roundtrip_identity": True, "qualified_module_registry_lookup_identity": mapped}
    aliases = {name: symbol(value) for name, value in vars(models).items() if isinstance(value, type) and hasattr(value, "__table__")}
    return {"base_registry_metadata_jsonb_clock_identity": True, "table_registration_order": list(metadata.tables), "mapper_count": len(models.Base.registry.mappers), "table_count": len(metadata.tables), "tables": tables, "mappers": mappers, "public_mapped_aliases": aliases, "core_classes": classes, "compile_errors": compile_errors, "public_all": getattr(models, "__all__", None)}


if __name__ == "__main__":
    mode = sys.argv[1]
    entry = sys.argv[2] if len(sys.argv) > 2 else "app.infrastructure.database.model_registry"
    if mode == "before" and not (OUT / "core-models-original-source.json").exists():
        path = BACKEND / "app/infrastructure/database/models.py"
        raw = path.read_bytes()
        assert hashlib.sha256(raw).hexdigest() == "cca0de0deb12e7cdc7368501e8a3ac0012e513d691ddcf10a3ead67ec4ec2ed0"
        (OUT / "core-models-original-source.json").write_text(json.dumps({"path": str(path.relative_to(ROOT)).replace("\\", "/"), "sha256": hashlib.sha256(raw).hexdigest(), "source": raw.decode("utf-8"), "migrations": {str(item.relative_to(ROOT)).replace("\\", "/"): hashlib.sha256(item.read_bytes()).hexdigest() for item in sorted((BACKEND / "alembic/versions").glob("*.py"))}}, indent=2) + "\n", encoding="utf-8")
    result = snapshot(entry)
    baseline_kind = "registry" if entry.endswith("model_registry") else "public"
    baseline = OUT / f"core-models-before-{baseline_kind}-metadata.json"
    if mode == "before":
        baseline.write_text(json.dumps(result, indent=2) + "\n", encoding="utf-8")
    else:
        expected = json.loads(baseline.read_text(encoding="utf-8"))
        assert result == expected
        if mode != "verify-owner":
            suffix = entry.rsplit(".", 1)[-1]
            (OUT / f"core-models-after-{suffix}-metadata.json").write_text(json.dumps(result, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"mode": mode, "entry": entry, "tables": result["table_count"], "mappers": result["mapper_count"], "core_classes": len(result["core_classes"]), "compile_errors": len(result["compile_errors"]), "annotation_results": {name: value["get_type_hints"] for name, value in result["core_classes"].items() if not value["get_type_hints"]["ok"]}, "matches_before": mode != "before"}, indent=2))
